  insert into core.roles (org_id, product_key, key, name)
  select p_org, 'erp', r.key, r.name from (values ('group_admin', 'Group admin'), ('system_admin', 'System admin'), ('principal', 'Principal'), ('coordinator', 'Coordinator'), ('class_teacher', 'Class teacher'), ('subject_teacher', 'Subject teacher'), ('accounts', 'Accounts'), ('hr', 'HR'), ('front_office', 'Front office'), ('transport', 'Transport manager'), ('librarian', 'Librarian'), ('store', 'Store and canteen'), ('warden', 'Warden'), ('counsellor', 'Counsellor'), ('nurse', 'Nurse'), ('security', 'Security'), ('driver', 'Driver / attendant'), ('portal', 'Parent and student portal')) as r(key, name)
